{["arg1"]=[[添加人物]],["arg2"]=[[dgwp17g]],["id"]=[[rlt_dgaddnpc12g]]},["rlt_dgaddnpc12h"]={["arg1"]=[[添加人物]],["arg2"]=[[dgwp17h]],["id"]=[[rlt_dgaddnpc12h]]},["rlt_dgaddnpc13"]={["arg1"]=[[添加人物]],["arg2"]=[[dgnpc06d]],["id"]=[[rlt_dgaddnpc13]]},["rlt_dgchoice01"]={["arg1"]=[[弹出选项框]],["arg2"]=[[YEL程墟：少侠，这地宫内秘密牵扯甚广，一旦现世，恐怕掀起偌大波澜。既然我们重返地面，不如将此间一事尘封入土，通通遗留在这地宫内为好。]],["arg3"]=[[同意]],["arg4"]=[[稍后]],["arg5"]=[[dgtext11;digongtp01]],["arg6"]=[[dgtext21]],["id"]=[[rlt_dgchoice01]]},["rlt_dghrfollow"]={["arg1"]=[[替换副本追随者]],["arg2"]=[[dgnpc06b]],["arg3"]=[[dgnpc06c]],["id"]=[[rlt_dghrfollow]]},["rlt_dgjsq01"]={["arg1"]=[[开启特殊计时器]],["arg2"]=0,["arg3"]=[[dgjsq01]],["arg4"]=[[delete;dgtext17;dgjsq02;dgaddfollow]],["id"]=[[rlt_dgjsq01]]},["rlt_dgjsq02"]={["arg1"]=[[开启特殊计时器]],["arg2"]=1.5,["arg3"]=[[dgjsq02]],["arg4"]=[[dgtext18;dgjsq03]],["id"]=[[rlt_dgjsq02]]},["rlt_dgjsq03"]={["arg1"]=[[开启特殊计时器]],["arg2"]=1.5,["arg3"]=[[dgjsq03]],["arg4"]=[[dgtext19;dgtextout01]],["id"]=[[rlt_dgjsq03]]},["rlt_dgjsq04"]={["arg1"]=[[开启特殊计时器]],["arg2"]=0,["arg3"]=[[dgjsq04]],["arg4"]=[[dgtext24;dgjsq05]],["id"]=[[rlt_dgjsq04]]},["rlt_dgjsq05"]={["arg1"]=[[开启特殊计时器]],["arg2"]=1,["arg3"]=[[dgjsq05]],["arg4"]=[[dgtext25;dghrfollow]],["id"]=[[rlt_dgjsq05]]},["rlt_dgtext02"]={["arg1"]=[[副本故事]],["arg2"]=[[你看到有人用无上指力在石壁上刻下一段诗句：;汉史标名氏，宕梁存慕丘。;非惟能抗节，更独抱先忧。;诗中似乎蕴含着深奥的武学哲理，一笔一划构成一个字，一字一句组成一首诗。看着石壁，你脑海中忽然悟到了什么。]],["arg3"]=[[1;1;1;1]],["id"]=[[rlt_dgtext02]]},["rlt_dgtext03"]={["arg1"]=[[副本故事]],["arg2"]=[[你看到有人用无上指力在石壁上刻下一段诗句：;全蜀悲衔璧，孤身欲断头。;湍奔砥柱屹，果硕剥阳留。;诗句中似乎蕴藏着一套高深的武学招式，你面对石壁盘膝而坐，开始感悟石壁上的武学。]],["arg3"]=[[1;1;1;1]],["id"]=[[rlt_dgtext03]]},["rlt_dgtext04"]={["arg1"]=[[副本故事]],["arg2"]=[[你看到有人用无上指力在石壁上刻下一段诗句：;片语消威猛，三军尽辑柔。;词严偏蔼若，气正一何遒。;诗句中似乎蕴藏着一套高深的武学招式，你面对石壁盘膝而坐，开始感悟石壁上的武学。]],["arg3"]=[[1;1;1;1]],["id"]=[[rlt_dgtext04]]},["rlt_dgtext05"]={["arg1"]=[[副本故事]],["arg2"]=[[你看到有人用无上指力在石壁上刻下一段诗句：;庙貌旒垂冕，祀将春复秋。;我来虔展拜，匪敢谓遨游。;石壁上的诗句似乎已经是结尾了，你面对石壁盘膝而坐，开始感悟诗句中蕴含的武学。]],["arg3"]=[[1;1;1;1]],["id"]=[[rlt_dgtext05]]},["rlt_dgtext06"]={["arg1"]=[[文本输出]],["arg2"]=[[石壁上面的内容你已经领悟了。]],["id"]=[[rlt_dgtext06]]},["rlt_dgtext07"]={["arg1"]=[[文本输出]],["arg2"]=[[你翻找了一遍，里面已经没有什么有价值的东西了。]],["id"]=[[rlt_dgtext07]]},["rlt_dgtext08"]={["arg1"]=[[文本输出]],["arg2"]=[[你试图掀开沉重的棺盖，但棺盖纹丝不动。只听一声微响，你似乎触发了什么机关，右侧墙壁自动分开，露出墙后面的秘密房间。]],["id"]=[[rlt_dgtext08]]},["rlt_dgtext09"]={["arg1"]=[[文本输出]],["arg2"]=[[你试图再次掀开沉重的棺盖，这一次棺盖被你掀开。你看向棺材内部，原来里面还藏着一条暗道。]],["id"]=[[rlt_dgtext09]]},["rlt_dgtext10"]={["arg1"]=[[文本输出]],["arg2"]=[[你手忙脚乱，仓促之间被陷阱所伤。]],["id"]=[[rlt_dgtext10]]},["rlt_dgtext11"]={["arg1"]=[[文本输出]],["arg2"]=[[你穿过了洞口，回到了地面上。你大口地呼吸着新鲜空气，打算将地宫内的一切都尘封进墓穴中，不带回地面的世界。]],["id"]=[[rlt_dgtext11]]},["rlt_dgtext12"]={["arg1"]=[[文本输出]],["arg2"]=[[你刚刚踏进房间，脚下似乎触动了什么机关，不过无事发生，看来是陷阱失效了。]],["id"]=[[rlt_dgtext12]]},["rlt_dgtext13"]={["arg1"]=[[文本输出]],["arg2"]=[[这是一具已经风干多时的尸体，你发现尸体身上似乎还有一些物品。]],["id"]=[[rlt_dgtext13]]},["rlt_dgtext14"]={["arg1"]=[[文本输出]],["arg2"]=[[你掀开棺盖，棺材里突然跳出来一个高大人偶，朝你发起攻击！]],["id"]=[[rlt_dgtext14]]},["rlt_dgtext15"]={["arg1"]=[[文本输出]],["arg2"]=[[剩余的书页被一阵阴风卷去，很快便消失的无影无踪。]],["id"]=[[rlt_dgtext15]]},["rlt_dgtext16"]={["arg1"]=[[文本输出]],["arg2"]=[[只见角落里瘫坐着一个人，此人身着盗墓连体服。他似乎被墓中机关所伤，正在吞服丹药，运功疗伤。]],["id"]=[[rlt_dgtext16]]},["rlt_dgtext17"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL程墟：这地宫大门只能进不能出，可叹有人竟从大门进入此地，真不知是好事还是坏事。]],["id"]=[[rlt_dgtext17]]},["rlt_dgtext18"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL程墟：在下程墟，以盗墓为生。前日我探得此处地宫方位，从地面上打了盗洞进入地宫。这地宫内机关重重，人偶更是无法可破，似乎只有这石壁上留下的武学才能破解人偶。]],["id"]=[[rlt_dgtext18]]},["rlt_dgtext19"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL程墟：那盗洞就在主墓室。我一路走来已被人偶打伤，无力施展这壁上武学，望少侠能参破石壁，习得人偶破解之法，带我一同从盗洞离开此地。多谢少侠。]],["id"]=[[rlt_dgtext19]]},["rlt_dgtext20"]={["arg1"]=[[文本输出]],["arg2"]=[[你被人偶击倒了，随后你两眼一黑，晕厥了过去。恍惚间，你只觉有人背着你快速跑动。不知过了多长时间，你才又醒了过来。]],["id"]=[[rlt_dgtext20]]},["rlt_dgtext21"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL程墟：看来少侠在此处尚有未完成之事。]],["id"]=[[rlt_dgtext21]]},["rlt_dgtext22"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL你被人偶击倒了，随后你两眼一黑，晕厥了过去。恍惚间，你只觉有人背着你快速跑动。不知过了多长时间，你才又醒了过来。]],["id"]=[[rlt_dgtext22]]},["rlt_dgtext24"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL程墟：呼…总算是出来了。]],["id"]=[[rlt_dgtext24]]},["rlt_dgtext25"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL程墟：少侠，盗洞出口就在前面，我们走吧。]],["id"]=[[rlt_dgtext25]]},["rlt_dgtext27"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL程墟：好不容易才脱离险境，还是抓紧时间离开地宫为妙。]],["id"]=[[rlt_dgtext27]]},["rlt_dgtext28"]={["arg1"]=[[文本输出]],["arg2"]=[[YEL程墟：少侠，你先看完这石壁上的内容，我们再走也不迟。]],["id"]=[[rlt_dgtext28]]},["rlt_dgtext29"]={["arg1"]=[[文本输出]],["arg2"]=[[棺材空空如也，里面的东西早已被人盗走了。]],["id"]=[[rlt_dgtext29]]},["rlt_dgtext32"]={["arg1"]=[[文本输出]],["arg2"]=[[人偶倒下后，通往密室的入口随之出现。]],["id"]=[[rlt_dgtext32]]},["rlt_dgtext33"]={["arg1"]=[[文本输出]],["arg2"]=[[人偶倒下后，你感到丹田内生出一股暖流，涌向奇经八脉。]],["id"]=[[rlt_dgtext33]]},["rlt_dgtextout01"]={["arg1"]=[[弹出文本]],["arg2"]=[[程墟与你同行。]],["id"]=[[rlt_dgtextout01]]},["rlt_dgtextout02"]={["arg1"]=[[弹出文本]],["arg2"]=[[人偶拦住了你的去路。]],["id"]=[[rlt_dgtextout02]]},["rlt_dgtextout03"]={["arg1"]=[[弹出文本]],["arg2"]=[[程墟喊住了你。]],["id"]=[[rlt_dgtextout03]]},["rlt_dgtextout06"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从石壁上领悟了武学  将军令]],["id"]=[[rlt_dgtextout06]]},["rlt_dgtextout07"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从石壁上领悟了招式  连横合纵]],["id"]=[[rlt_dgtextout07]]},["rlt_dgtextout08"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从石壁上领悟了招式  卧薪尝胆]],["id"]=[[rlt_dgtextout08]]},["rlt_dgtextout09"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从石壁上领悟了招式  负荆请罪]],["id"]=[[rlt_dgtextout09]]},["rlt_dgtextout10"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从石壁上领悟了招式  围魏救赵]],["id"]=[[rlt_dgtextout10]]},["rlt_dgtextout11"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从石壁上领悟了招式  雁门降胡]],["id"]=[[rlt_dgtextout11]]},["rlt_dgtextout12"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从石壁上领悟了招式  南征百越]],["id"]=[[rlt_dgtextout12]]},["rlt_dgtextout13"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从石壁上领悟了招式  退避三舍]],["id"]=[[rlt_dgtextout13]]},["rlt_dgtextout14"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从石壁上领悟了招式  尊王攘夷]],["id"]=[[rlt_dgtextout14]]},["rlt_dgtextout15"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从石壁上领悟了招式  秉公执法]],["id"]=[[rlt_dgtextout15]]},["rlt_dgtextout16"]={["arg1"]=[[弹出文本]],["arg2"]=[[你从秘典上领悟了招式  伏尸百万]],["id"]=[[rlt_dgtextout16]]},["rlt_dgtextout17"]={["arg